// Golden test: every number below was generated by the website's own functions (meshcore-insights
// src/lib/tools/airtime.ts + src/lib/tools/presets.ts, via scripts/plan-tools-golden.ts) and stored in
// test/fixtures/plan_tools_golden.json. The Dart port must reproduce them.
import 'package:flutter_test/flutter_test.dart';
import 'package:meshsonar/core/plan/airtime_calc.dart';
import 'package:meshsonar/core/plan/presets_calc.dart';

import 'plan_golden.dart';

AirRadio _radio(Map<String, dynamic> j) =>
    AirRadio(sf: j['sf'] as int, bwKHz: (j['bwKHz'] as num).toDouble(), cr: j['cr'] as int, preamble: j['preamble'] as int?);

PacketSpec _spec(Map<String, dynamic> j) => PacketSpec(
      PayloadKind.values.byName(j['kind'] as String),
      chars: j['chars'] as int?,
      nameLen: j['nameLen'] as int?,
      withLocation: j['withLocation'] as bool? ?? true,
      customBytes: j['customBytes'] as int?,
      hops: j['hops'] as int? ?? 0,
      hashSize: j['hashSize'] as int? ?? 1,
      transport: j['transport'] as bool? ?? false,
    );

void main() {
  final g = loadPlanGolden();
  final a = g['airtime'] as Map<String, dynamic>;
  final p = g['presets'] as Map<String, dynamic>;

  test('time on air matches the website for 7 radios x 6 packet sizes', () {
    final rows = a['toa'] as List;
    expect(rows.length, 42);
    for (final r in rows.cast<Map<String, dynamic>>()) {
      final t = timeOnAir(r['bytes'] as int, _radio(r['radio'] as Map<String, dynamic>));
      final tag = '${r['radio']} ${r['bytes']} B';
      expect(t.totalMs, closeTo((r['totalMs'] as num).toDouble(), 1e-9), reason: tag);
      expect(t.payloadSymbols, r['payloadSymbols'], reason: tag);
      expect(t.preambleMs, closeTo((r['preambleMs'] as num).toDouble(), 1e-9), reason: tag);
      expect(t.tsymMs, closeTo((r['tsymMs'] as num).toDouble(), 1e-12), reason: tag);
      expect(t.ldro, r['ldro'], reason: tag);
    }
  });

  test('packet byte builder matches, including the firmware-limit messages', () {
    for (final r in (a['packets'] as List).cast<Map<String, dynamic>>()) {
      final b = packetBytes(_spec(r['spec'] as Map<String, dynamic>));
      expect([b.header, b.transport, b.pathLen, b.path, b.payload, b.total], [r['header'], r['transport'], r['pathLen'], r['path'], r['payload'], r['total']],
          reason: '${r['spec']}');
      expect(b.overLimit, r['overLimit'], reason: '${r['spec']}');
    }
  });

  test('flood airtime and relay delay windows match', () {
    for (final f in (a['floods'] as List).cast<Map<String, dynamic>>()) {
      final r = floodAirtime(_spec(f['spec'] as Map<String, dynamic>), f['relays'] as int, _radio(f['radio'] as Map<String, dynamic>));
      expect(r.totalMs, closeTo((f['totalMs'] as num).toDouble(), 1e-9));
      final steps = f['steps'] as List;
      expect(r.steps.length, steps.length);
      for (var i = 0; i < steps.length; i++) {
        expect(r.steps[i].bytes, steps[i]['bytes']);
        expect(r.steps[i].ms, closeTo((steps[i]['ms'] as num).toDouble(), 1e-9));
      }
    }
    for (final d in (a['delays'] as List).cast<Map<String, dynamic>>()) {
      final w = relayDelayWindow(packetBytes(_spec(d['spec'] as Map<String, dynamic>)), txdelay: (d['txdelay'] as num).toDouble(), radio: _radio(d['radio'] as Map<String, dynamic>));
      expect(w.tMs, closeTo((d['tMs'] as num).toDouble(), 1e-9));
      expect(w.maxMs, closeTo((d['maxMs'] as num).toDouble(), 1e-9));
      expect(w.meanMs, closeTo((d['meanMs'] as num).toDouble(), 1e-9));
    }
  });

  test('raw header parsing, duty cycle, ALOHA and observation bytes match', () {
    for (final r in (a['raws'] as List).cast<Map<String, dynamic>>()) {
      final h = parseRawHeader(r['hex'] as String);
      final want = r['header'] as Map<String, dynamic>?;
      if (want == null) {
        expect(h, isNull, reason: r['hex'] as String);
      } else {
        expect([h!.bytes, h.routeType, h.payloadType, h.hashSize, h.hopCount], [want['bytes'], want['routeType'], want['payloadType'], want['hashSize'], want['hopCount']],
            reason: r['hex'] as String);
      }
    }
    for (final d in (a['duty'] as List).cast<Map<String, dynamic>>()) {
      expect(dutyCyclePct((d['af'] as num).toDouble()), closeTo((d['pct'] as num).toDouble(), 1e-12));
    }
    for (final d in (a['aloha'] as List).cast<Map<String, dynamic>>()) {
      expect(alohaCollision((d['g'] as num).toDouble()), closeTo((d['p'] as num).toDouble(), 1e-12));
    }
    expect(observationBytes(const RawHeader(bytes: 80, routeType: 1, payloadType: 5, hashSize: 1, hopCount: 2), 4, 1), a['observation']);
  });

  test('the load what-if (projectLoad) matches the website for five scenarios', () {
    final cases = (a['whatIfs'] as List).cast<Map<String, dynamic>>();
    expect(cases.length, 5);
    for (final c in cases) {
      final m = c['mix'] as Map<String, dynamic>;
      final w = c['w'] as Map<String, dynamic>;
      final r = projectLoad(
        LoadMix(fixedS: (m['fixedS'] as num).toDouble(), floodByHopS: [for (final v in m['floodByHopS'] as List) (v as num).toDouble()], advertByHopS: [for (final v in m['advertByHopS'] as List) (v as num).toDouble()]),
        WhatIf(
            repeaters: w['repeaters'] as int,
            links: w['links'] as int,
            addRepeaters: w['addRepeaters'] as int,
            floodMax: w['floodMax'] as int,
            advertIntervalH: (w['advertIntervalH'] as num).toDouble(),
            baselineAdvertIntervalH: (w['baselineAdvertIntervalH'] as num).toDouble()),
      );
      for (final (name, got) in [('k', r.k), ('kNew', r.kNew), ('rho', r.rho), ('total', r.total), ('flood', r.flood), ('advert', r.advert), ('fixed', r.fixed)]) {
        expect(got, closeTo((c[name] as num).toDouble(), 1e-9), reason: '$name for $w');
      }
    }
  });

  test('sensitivity and budget change match the website for every BW x SF', () {
    final sens = (p['sens'] as List).cast<Map<String, dynamic>>();
    expect(sens.length, 24);
    for (final s in sens) {
      expect(sensitivityDbm(s['sf'] as int, (s['bw'] as num).toDouble()), closeTo((s['dbm'] as num).toDouble(), 1e-9));
      expect(deltaDb(s['sf'] as int, (s['bw'] as num).toDouble()), closeTo((s['deltaUs'] as num).toDouble(), 1e-9));
    }
  });

  test('preset rows match the website (3 base radios x CR 4/5 and 4/8)', () {
    for (final set in (p['rows'] as List).cast<Map<String, dynamic>>()) {
      final base = _radio(set['base'] as Map<String, dynamic>);
      final rows = presetRows(cr: set['cr'] as int, repeaters: set['repeaters'] as int, base: base);
      final want = (set['rows'] as List).cast<Map<String, dynamic>>();
      expect(rows.length, want.length);
      for (var i = 0; i < rows.length; i++) {
        expect(rows[i].sf, want[i]['sf']);
        expect(rows[i].bwKHz, want[i]['bwKHz']);
        expect(rows[i].isBase, want[i]['isBase']);
        expect(rows[i].toaMs, closeTo((want[i]['toaMs'] as num).toDouble(), 1e-9));
        expect(rows[i].sensitivity, closeTo((want[i]['sensitivityDbm'] as num).toDouble(), 1e-9));
        expect(rows[i].delta, closeTo((want[i]['deltaDb'] as num).toDouble(), 1e-9));
        expect(rows[i].floodLoadMs, closeTo((want[i]['floodLoadMs'] as num).toDouble(), 1e-8));
      }
    }
  });

  test('odds shift matches the website', () {
    for (final s in (p['shifts'] as List).cast<Map<String, dynamic>>()) {
      expect(shiftOdds((s['p'] as num).toDouble(), (s['delta'] as num).toDouble()), closeTo((s['q'] as num).toDouble(), 1e-12));
    }
  });
}
